const fs=require('node:fs'),path=require('node:path');const {chromium}=require('playwright');
const repo=process.env.ASC_REPO||path.resolve(__dirname,'../..');
const names=[...fs.readFileSync(path.join(repo,'js/db.js'),'utf8').matchAll(/export\s+(?:async\s+)?(?:function|const|let|class)\s+(\w+)/g)].map(m=>m[1]);
const session={user:{id:'ui-audit',email:'ui@example.invalid'},expires_at:1999999999};
const profile={id:'ui-audit',full_name:'UI Audit',role:'admin',onboarded_at:'2026-10-15'};
const set={id:'set-one',public_code:'ASC-2026-0003',status:'in_storage',paid:false,created_at:'2026-10-14',checkin_at:'2026-10-14',vehicle:{id:'v-one',plate:'ZG100AA',customer:{id:'c-one',name:'Test Kupac',phone:'',email:''}},tires:[],photos:[],location:null};
const overrides={getSession:()=>`async()=>window.__signedOut?null:session`,loadMyProfile:()=>`async()=>({...${JSON.stringify(profile)},...(window.__onboarding?{onboarded_at:null}:{})})`,loadStorageSet:()=>`async()=>(${JSON.stringify(set)})`,signUp:()=>`async()=>({needsConfirm:true})`,onAuthChange:()=>`()=>({data:{subscription:{unsubscribe(){}}}})`,healthStats:()=>`async()=>({inventory:0,todayCheckIns:0,todayPickups:0,lastBackup:null})`,countsByStatus:()=>`async()=>({in_storage:0,reserved:0,checked_out:0,missing:0})`,signedPhotoUrls:()=>`async()=>({})`,countLocations:()=>`async()=>1`,countPendingApprovals:()=>`async()=>0`,ADMIN_ROLES:()=>`['admin','manager']`,OWNER_EMAIL:()=>`'owner@example.invalid'`,isAdminRole:()=>`role=>['admin','manager'].includes(role)`,isOwnerEmail:()=>`()=>false`,locationLabel:()=>`loc=>[loc.zone,loc.rack,loc.slot].filter(Boolean).join('-')`,maskEmail:()=>`email=>email`,createStorageSet:()=>`async()=>"ASC-2026-0099"`,findPossibleDuplicates:()=>`async()=>[]`};
const db=`const session=${JSON.stringify(session)};`+names.map(n=>`export const ${n}=${overrides[n]?overrides[n]():/^(list|recent|freeSlots|loadAudit|warehouse)/.test(n)?'async()=>[]':/count/.test(n)?'async()=>0':'async()=>null'};`).join('\n');
const auth=`const session=${JSON.stringify(session)};export const isConfigured=()=>true;const chain=new Proxy({}, {get(_,p){if(p==='then')return (r)=>Promise.resolve(r({data:[],error:null}));return ()=>chain}});export const supabase={auth:{getSession:async()=>({data:{session:window.__signedOut?null:session},error:null}),onAuthStateChange:()=>({data:{subscription:{unsubscribe(){}}}}),signOut:async()=>{},updateUser:async()=>({}),signInWithPassword:async()=>({})},from:()=>chain,rpc:async()=>({data:[],error:null}),channel:()=>chain,removeChannel:()=>{},storage:{from:()=>chain}};`;
async function start(){return chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||process.env.CHROME_PATH||'/usr/bin/chromium',args:['--no-sandbox','--enable-unsafe-swiftshader']});}
async function pageFor(browser,{width=390,height=844,onboarding=false,theme='light',signedOut=false}={}){const context=await browser.newContext({viewport:{width,height},reducedMotion:'reduce',serviceWorkers:'block'});await context.addInitScript(({onboarding,theme,signedOut})=>{window.__signedOut=signedOut;window.__onboarding=onboarding;localStorage.setItem('asc.theme',theme);sessionStorage.setItem('asc.splash.warm','1');}, {onboarding,theme,signedOut});
await context.route('**/*',async route=>{const u=new URL(route.request().url());if(u.origin!=='http://asc.test')return route.fulfill({status:200,contentType:'text/javascript',body:''});if(u.pathname==='/js/db.js')return route.fulfill({contentType:'text/javascript',body:db});if(u.pathname==='/js/supabaseClient.js')return route.fulfill({contentType:'text/javascript',body:auth});if(u.pathname==='/js/config.js')return route.fulfill({contentType:'text/javascript',body:'export const config={SUPABASE_URL:"https://synthetic.invalid",APP_BASE_URL:"http://asc.test/app/"};'});if(u.pathname.endsWith('/agent-config.js'))return route.fulfill({contentType:'text/javascript',body:'window.ASC_AGENT_URL="";'});const file=path.join(repo,u.pathname);if(fs.existsSync(file)&&fs.statSync(file).isFile())return route.fulfill({contentType:({'.js':'text/javascript','.css':'text/css','.html':'text/html','.woff2':'font/woff2','.png':'image/png','.jpg':'image/jpeg','.svg':'image/svg+xml','.webmanifest':'application/manifest+json'})[path.extname(file)]||'text/plain',body:fs.readFileSync(file)});return route.fulfill({status:404,body:''});});
const page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));return {page,context,errors};}
module.exports={start,pageFor,repo};
